move.content:
const s = JSON.parse(state);
const E = s.packages.engine;
const time = E.utilities.time.properties.state;
const kb = E.packages.controllers.utilities['keyboard-0'];
const pt = E.packages.controllers.utilities['pointer-0'];

const me = s.packages.avatar;
const d = me.properties.meta.data;
const rig = s.packages.rig.properties.meta.data;
const dt = Math.min(time.delta, 0.1);
const radius = d.radius || 0.45;

const keys = kb ? kb.properties.state.digital : [];
const on = k => keys.indexOf(k) >= 0;

// The camera is what "forward" means in a third person view, so it is turned
// first and the avatar is steered relative to where it ended up.
let yaw = rig.yaw || 0;
let pitch = rig.pitch != null ? rig.pitch : -0.28;

if (pt) {
	const a = pt.properties.state.analog;
	yaw -= (a.dx || 0) * 3.2;
	pitch += (a.dy || 0) * 3.2;
	// Negative pitch swings the eye up and behind, which is where a third
	// person view wants to sit; positive brings it down to look up.
	pitch = Math.max(-1.0, Math.min(0.30, pitch));
}

const forward = (on('KeyW') || on('ArrowUp') ? 1 : 0) - (on('KeyS') || on('ArrowDown') ? 1 : 0);
const strafe = (on('KeyD') || on('ArrowRight') ? 1 : 0) - (on('KeyA') || on('ArrowLeft') ? 1 : 0);

const sy = Math.sin(yaw), cy = Math.cos(yaw);
let mx = -sy * forward + cy * strafe;
let mz = -cy * forward - sy * strafe;

const push = Math.hypot(mx, mz);
const drive = Math.min(1, push);

if (push > 1e-6) { mx /= push; mz /= push; }

// Backing up is the one time a figure should not point where it is going,
// and it is also the one time the backward clip suits it. The same condition
// decides both.
const backing = forward < 0 && Math.abs(forward) >= Math.abs(strafe);

const running = on('ShiftLeft') || on('ShiftRight');
const rate = running ? 8.4 : 3.4;

const probe = me.utilities.ground.properties.state;
const hits = probe ? probe.hits : null;

// The probe looks down from well overhead, so its answers arrive highest
// first. Taking the first of them puts the avatar on the roof of anything she
// walks beneath. What is underfoot is the highest surface that is not above
// what she could step onto, and while she is in the air nothing above her
// counts at all, or jumping under a platform would hoist her onto it at the
// top of the arc.
const reach = d.grounded ? (d.step || 0.9) : 0.05;

let surface = null;

if (hits) {
	for (const hit of hits) {
		if (hit.point[1] <= d.position[1] + reach) { surface = hit; break; }
	}
}

// Slope normalisation, as on foot elsewhere: a climb costs ground covered
// rather than adding to the speed.
let grade = 0;

if (surface && surface.normal && Math.abs(surface.normal[1]) > 1e-3) {
	const n = surface.normal;
	grade = -(mx * n[0] + mz * n[2]) / n[1];
}

// The overlap that stops a body is a frame behind it, so a step larger than
// the body cannot be caught before it has passed through something thin.
// Capping the step against the radius bounds that, and only ever bites at a
// frame rate far below playable.
const step = Math.min(
	rate * drive * dt / Math.sqrt(1 + grade * grade),
	radius * 0.7
);

let px = d.position[0] + mx * step;
let pz = d.position[2] + mz * step;

// Anything solid is pushed out of horizontally, so running into a pillar
// stops the avatar rather than lifting them onto it.
const bump = me.utilities.bump.properties.state;

if (bump && bump.hits) {
	for (const hit of bump.hits) {

		const depth = radius - hit.distance;
		if (depth <= 0) continue;

		let nx = hit.normal[0];
		let nz = hit.normal[2];

		// A negative distance means the body is already inside. Following the
		// nearest face out of a thin obstacle can eject it through the far
		// side, so it retreats the way it came in instead, which is known here
		// and not to the engine.
		if (hit.distance < 0 && (mx !== 0 || mz !== 0)) {
			nx = -mx;
			nz = -mz;
		}

		const flat = Math.hypot(nx, nz);
		if (flat < 1e-4) continue;

		px += (nx / flat) * depth;
		pz += (nz / flat) * depth;
	}
}

const edge = 44;
px = Math.max(-edge, Math.min(edge, px));
pz = Math.max(-edge, Math.min(edge, pz));

// Falling and landing. The probe reports whatever is directly underneath,
// which is the top of a block when there is one, so the same arithmetic
// lands on the ground and on the course.
const floor = surface ? surface.point[1] : d.position[1];

let py = d.position[1];
let vy = d.vy || 0;
let grounded = d.grounded ? 1 : 0;
let jumped = 0;

if (grounded && on('Space')) {
	vy = 9.4;
	grounded = 0;
	jumped = 1;
}

vy -= 26 * dt;
py += vy * dt;

if (vy <= 0 && py <= floor) {
	py = floor;
	vy = 0;
	grounded = 1;
} else if (py > floor + 0.02) {
	grounded = 0;
}

// Nothing here belongs below the course; a bad frame should not be permanent.
if (py < -60) { py = floor; vy = 0; }

// The avatar turns to face the way it is going, rather than snapping.
let facing = d.facing || 0;

if (drive > 0.01) {
	const ax = backing ? -mx : mx;
	const az = backing ? -mz : mz;
	const want = Math.atan2(-ax, -az);
	let turn = ((want - facing + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
	facing += turn * Math.min(1, 14 * dt);
}

// Which clip suits what the avatar is doing. The model has no jump, so it
// holds its idle pose in the air.
let clip = 'Idle';
let ratio = 1;

if (!grounded) {
	clip = 'Idle';
} else if (drive > 0.05) {
	if (backing) {
		clip = 'WalkingBack';
		ratio = 1.1;
	} else {
		clip = 'Walking';
		ratio = running ? 1.9 : 1.05;
	}
}

// The camera rig chases the avatar rather than being welded to it, which
// keeps a landing from jolting the view.
const chase = Math.min(1, 12 * dt);
const rx = (rig.position ? rig.position[0] : px) + (px - (rig.position ? rig.position[0] : px)) * chase;
const ry = (rig.position ? rig.position[1] : py) + (py - (rig.position ? rig.position[1] : py)) * chase;
const rz = (rig.position ? rig.position[2] : pz) + (pz - (rig.position ? rig.position[2] : pz)) * chase;

const moved = Math.hypot(px - d.position[0], pz - d.position[2]);

const patch = { packages: {
	avatar: { properties: { meta: { data: {
		position: [px, py, pz],
		rotation: [0, facing, 0],
		facing: facing,
		vy: vy,
		grounded: grounded,
		clip: clip,
		grade: grade,
		speed: dt > 0 ? moved / dt : 0,
		distance: (d.distance || 0) + moved
	} } } },
	rig: { properties: { meta: { data: {
		position: [rx, ry, rz],
		rotation: [0, yaw, 0],
		yaw: yaw,
		pitch: pitch
	} } }, packages: { arm: { properties: { meta: { data: {
		rotation: [pitch, 0, 0]
	} } } } } }
} };

// A clip is only restarted when it actually changes.
if (d.clip !== clip) {
	patch.packages.avatar.packages = { body: { utilities: { motion: {
		properties: { data: { clip: clip, speed: ratio, play: true } }
	} } } };
} else {
	patch.packages.avatar.packages = { body: { utilities: { motion: {
		properties: { data: { speed: ratio } }
	} } } };
}

if (jumped) {
	patch.packages.avatar.properties.meta.data.jumps = (d.jumps || 0) + 1;
}

return JSON.stringify(patch);

lock.content:
const s = JSON.parse(state);
if (s.packages.engine.utilities.display.properties.data.cursor === 'locked') return;
return JSON.stringify({ packages: { engine: { utilities: { display: { properties: { data: { cursor: 'locked' } } } } } } });

status.content:
const s = JSON.parse(state);
const t = s.packages.engine.utilities.time.properties.state;
if (t.frame % 20 !== 0) return;
const d = s.packages.avatar.properties.meta.data;
const m = s.packages.avatar.packages.body.utilities.mesh.properties.state;
const line = (m && m.loaded ? d.clip : 'loading avatar') +
	'   ' + (d.speed || 0).toFixed(1) + 'm/s' +
	'   ' + Math.round(d.distance || 0) + 'm' +
	'   jumps ' + (d.jumps || 0) +
	(d.grounded ? '' : '   airborne');
if (s.packages.hud.utilities.readout.content === line) return;
return JSON.stringify({ packages: { hud: { utilities: { readout: { content: line } } } } });
